package com.axiom.application.pipeline; import com.axiom.domain.pipeline.FileCategory;import org.springframework.stereotype.Component;
@Component public class ChangedFileClassifier {public FileCategory classify(String p){String x=p.toLowerCase();if(x.startsWith("src/test/")||x.startsWith("tests/")||x.matches(".*(test|spec)\\.(java|ts|js)$"))return FileCategory.TEST_SOURCE;if(x.startsWith("src/main/")||x.startsWith("app/")||x.startsWith("lib/"))return FileCategory.PRODUCTION_SOURCE;if(x.equals("pom.xml")||x.equals("build.gradle")||x.equals("build.gradle.kts")||x.equals("package.json")||x.equals("requirements.txt")||x.equals("pyproject.toml"))return FileCategory.DEPENDENCY_MANIFEST;if(x.endsWith("lock.json")||x.endsWith(".lock")||x.endsWith("gradle.lockfile"))return FileCategory.DEPENDENCY_LOCKFILE;if(x.startsWith(".github/workflows/"))return FileCategory.CI_CONFIGURATION;if(x.equals("dockerfile")||x.startsWith("k8s/")||x.startsWith("terraform/")||x.endsWith(".tf"))return FileCategory.INFRASTRUCTURE_CONFIGURATION;if(x.contains("migration/"))return FileCategory.DATABASE_MIGRATION;if(x.contains("application.")||x.startsWith("config/"))return FileCategory.APPLICATION_CONFIGURATION;if(x.endsWith(".md"))return FileCategory.DOCUMENTATION;return FileCategory.UNKNOWN;}}
